    },
    {
      "card_ids": ["C34"],
      "claim": "CAB, a fused heteroaromatic piperazine analogue, shows near-complete oral bioavailability in humans, directly supporting high F for the query's piperazine-containing heteroaromatic system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "SB-742457, a piperazine-containing heteroaromatic compound, demonstrated excellent oral bioavailability in phase III clinical trials, supporting high F for the query's piperazine-heteroaromatic motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "ZL-2201, a heteroaromatic amine with an N-alkylated fused bicyclic core, has predicted human absolute oral bioavailability of approximately 70%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Alfuzosin, a heteroaromatic amide with a basic amine, has mean absolute oral bioavailability of 64% in healthy volunteers, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    }
